INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "刘汉宏在台州被捕送董昌后遭处决", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月条；具体日未载", "dynasty": "唐", "description": "台州刺史杜雄诱捕刘汉宏，交给董昌；刘汉宏随后被斩。", "phases": [], "location_name": "台州、越州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1f464a51-8c74-5e42-b3e3-a2e55d25ab82"}, {"title": "董昌移镇越州，以钱镠知杭州事", "start_year": 886, "end_year": 886, "time_original": "刘汉宏被斩后；具体日未载", "dynasty": "唐", "description": "董昌移镇越州，自称知浙东军府事，任钱镠知杭州事。", "phases": [], "location_name": "越州、杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "abaa811e-e44d-5fa2-bc7c-41fa0c646746"}, {"title": "王重荣函送襄王煴首级至行在", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月条；具体日未载", "dynasty": "唐", "description": "王重荣把襄王煴首级函送皇帝行在；刑部建议公开献馘并由百官庆贺。", "phases": [], "location_name": "河中、兴元行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f94e7f2c-67f6-5468-9a98-8d91e098d53e"}, {"title": "殷盈孙建议废襄王煴为庶人、缓行献馘礼", "start_year": 886, "end_year": 886, "time_original": "襄王煴首级送至行在后；具体日未载", "dynasty": "唐", "description": "太常博士殷盈孙上议，主张将襄王煴废为庶人并葬其首，待朱玫首级送至再行献馘称贺；朝廷采纳。", "phases": [], "location_name": "兴元行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10f6bd19-42bc-5c9d-a0e6-64f81641c9fa"}, {"title": "刘经袭李罕之于渑池，败走洛阳", "start_year": 886, "end_year": 886, "time_original": "光启二年十二月条；具体日未载", "dynasty": "唐", "description": "刘经惧李罕之难制，出兵袭渑池，被李罕之击败，弃洛阳逃走；李罕之追击。", "phases": [], "location_name": "渑池、洛阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a6c3c09e-d521-545a-9f7e-dc0b6f2a9f32"}, {"title": "张全义转与李罕之合兵攻河阳", "start_year": 886, "end_year": 886, "time_original": "刘经在渑池战败后；具体日未载", "dynasty": "唐", "description": "刘经先遣张全义阻李罕之渡河。张全义后来与李罕之合兵攻河阳，仍被刘经击败，二人退保怀州。", "phases": [], "location_name": "河阳、怀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2ba6a056-0ab7-5f1e-bb28-70b70d9efc01"}, {"title": "孙儒、刘建锋、马殷曾在蔡州抵黄巢", "start_year": null, "end_year": null, "time_original": "“初”追叙黄巢时事；确年待考", "dynasty": "唐", "description": "《通鉴》追叙孙儒、刘建锋在蔡州戍守抗黄巢，马殷隶军中；秦宗权叛后几人转属其部。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9752f46d-1b46-5e11-9286-1325f912a670"}, {"title": "孙儒攻陷郑州，李璠奔大梁", "start_year": 886, "end_year": 886, "time_original": "光启二年岁末总述；具体月日未载", "dynasty": "唐", "description": "秦宗权遣孙儒攻陷郑州，刺史李璠逃往大梁。", "phases": [], "location_name": "郑州、大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7dfd77c9-816b-5fd8-9fe0-92afbc8e775f"}, {"title": "孙儒取河阳并自称节度使", "start_year": 886, "end_year": 886, "time_original": "郑州陷后；具体月日未载", "dynasty": "唐", "description": "孙儒继而攻陷河阳，诸葛仲方逃往大梁；孙儒自称节度使，张全义据怀州、李罕之据泽州抵御。", "phases": [], "location_name": "河阳、怀州、泽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "38cf7e78-3544-5d64-81df-b7e44f08d627"}, {"title": "张佶与刘建锋在秦宗权幕下相善", "start_year": null, "end_year": null, "time_original": "“初”追叙至秦宗权时期；确年待考", "dynasty": "唐", "description": "《通鉴》追叙张佶离开宣州，途经蔡州时被秦宗权留为行军司马；张佶向刘建锋表达对秦宗权的担忧，二人后来相善。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "de2e6b98-ef65-5d38-a8b0-9f7841621e14"}, {"title": "杨行愍部在褚城败魏虔", "start_year": 886, "end_year": 886, "time_original": "光启二年岁末条；具体月日未载", "dynasty": "唐", "description": "张翱遣魏虔率军攻庐州，庐州刺史杨行愍遣田頵、李神福、张训抵御，于褚城败魏虔。", "phases": [], "location_name": "庐州、褚城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d637a6c5-e672-563b-8a22-1c3eee30b151"}, {"title": "许勍袭舒州，陶雅奔庐州", "start_year": 886, "end_year": 886, "time_original": "褚城战后条；具体月日未载", "dynasty": "唐", "description": "滁州刺史许勍袭舒州，刺史陶雅逃往庐州。", "phases": [], "location_name": "舒州、庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "86231202-02e4-5774-90ba-d472f79c332b"}, {"title": "高骈命杨行愍更名杨行密", "start_year": 886, "end_year": 886, "time_original": "光启二年岁末条；具体月日未载", "dynasty": "唐", "description": "高骈命杨行愍更名为杨行密；这是同一人改名，不另建人物实体。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e3eff3f4-c57e-5675-8d4d-637b71faf257"}, {"title": "朱瑾以婚礼掩护袭泰宁治所，逐齐克让", "start_year": 886, "end_year": 886, "time_original": "光启二年是岁；具体月日未载", "dynasty": "唐", "description": "朱瑾以求婚及迎亲为掩护，将兵器暗藏车队，入城后发动伏兵，逐泰宁节度使齐克让，自称留后；朝廷随后任朱瑾为泰宁节度使。", "phases": [], "location_name": "衮州（底本文字待校）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "71c443ba-4aef-52b7-b1cb-7fcd4767fd3c"}, {"title": "周通攻鄂州，路审中逃离", "start_year": 886, "end_year": 886, "time_original": "光启二年是岁；具体月日未载", "dynasty": "唐", "description": "周通攻鄂州，路审中离开。", "phases": [], "location_name": "鄂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d10f6d10-4e11-5151-8a20-bfa08fc99da1"}, {"title": "杜洪入鄂，自称武昌留后并获朝廷授任", "start_year": 886, "end_year": 886, "time_original": "路审中离城后；具体月日未载", "dynasty": "唐", "description": "杜洪趁鄂州空虚进入，自称武昌留后，朝廷随后授任。", "phases": [], "location_name": "鄂州、武昌", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4708c571-405c-5d34-8cb7-2e2ad7b853f9"}, {"title": "邓进思乘虚攻陷岳州", "start_year": 886, "end_year": 886, "time_original": "杜洪离岳州后；具体月日未载", "dynasty": "唐", "description": "邓进思趁岳州空虚攻陷该州。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "37165ed9-ff3c-5ee1-abd7-84001ce5de06"}, {"title": "秦宗言久围荆南未克而撤", "start_year": 886, "end_year": 886, "time_original": "至光启二年岁末；围城起点待考", "dynasty": "唐", "description": "秦宗言围荆南历时约二年，守城将领原仓库底本作“张环”，固定异文作“张瑰”；城中粮食匮乏，秦宗言最终未克而去。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "04dba2a5-9ab8-52f7-ad49-23de9687ac08"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

